import re
import unicodedata

def slugify(texte):
    if not texte:
        return ""
    plat = unicodedata.normalize("NFKD", texte)
    plat = "".join(c for c in plat if not unicodedata.combining(c)).lower()
    plat = re.sub(r"[^a-z0-9]+", "-", plat)
    return plat.strip("-")

